def coerce(kind: str, value):
    """Coerce a raw cell value to the column's Python type, filling blanks."""
    blank = value is None or (isinstance(value, str) and value.strip() == "")
    if kind in ("str", "text"):
        return "" if blank else str(value).strip()
    if kind in ("int", "bigint"):
        if blank:
            return 0
        try:
            return round(float(value))
        except (TypeError, ValueError):
            return 0
    if kind == "num":
        if blank:
            return 0
        try:
            return float(value)
        except (TypeError, ValueError):
            return 0
    if kind == "bool":
        if blank:
            return False
        if isinstance(value, bool):
            return value
        return str(value).strip().upper() in ("TRUE", "1", "YES", "Y")
    if kind == "date":
        if blank:
            return DATE_SENTINEL
        if isinstance(value, datetime.datetime):
            return value.date()
        if isinstance(value, datetime.date):
            return value
        return DATE_SENTINEL
    raise ValueError(f"unknown kind: {kind}")
